fix:
Use thread-local counters that are only periodically merged/aggregated, eliminating cache-coherency bottlenecking on the hot path.
```rust
thread_local! {
    static LOCAL_COUNTER: Cell<u64> = Cell::new(0);
}

fn handle_request_correct() {
    LOCAL_COUNTER.with(|c| {
        let val = c.get() + 1;
        if val >= 1000 { // Batch updates to the global pool
            GLOBAL_COUNTER.fetch_add(val, Ordering::Relaxed);
            c.set(0);
        } else {
            c.set(val);
        }
    });
}
```
